// Re-applies the Windows build fixes every time android/ is generated by `expo prebuild` (android/ is not committed).
const fs = require('fs');
const path = require('path');
const { withAppBuildGradle, withDangerousMod, withAndroidManifest } = require('expo/config-plugins');
const { addCmakeObjectPathMax, setGradleNetworkTimeout, addWorkManagerProguardRules, shouldAllowCleartext, setCleartextTraffic } = require('./androidBuildFixes');

function withCmakeObjectPathMax(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') {
      throw new Error('withAndroidBuildFixes: only a Groovy app/build.gradle is supported');
    }
    cfg.modResults.contents = addCmakeObjectPathMax(cfg.modResults.contents);
    return cfg;
  });
}

function withGradleNetworkTimeout(config) {
  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const file = path.join(cfg.modRequest.platformProjectRoot, 'gradle', 'wrapper', 'gradle-wrapper.properties');
      const current = await fs.promises.readFile(file, 'utf8');
      const next = setGradleNetworkTimeout(current);
      if (next !== current) await fs.promises.writeFile(file, next);
      return cfg;
    },
  ]);
}

function withWorkManagerProguardRules(config) {
  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const file = path.join(cfg.modRequest.platformProjectRoot, 'app', 'proguard-rules.pro');
      let current = '';
      try {
        current = await fs.promises.readFile(file, 'utf8');
      } catch (e) {
        if (e.code !== 'ENOENT') throw e;
      }
      const next = addWorkManagerProguardRules(current);
      if (next !== current) await fs.promises.writeFile(file, next);
      return cfg;
    },
  ]);
}

function withCleartextTraffic(config) {
  return withAndroidManifest(config, (cfg) => {
    cfg.modResults = setCleartextTraffic(cfg.modResults, shouldAllowCleartext(process.env));
    return cfg;
  });
}

module.exports = function withAndroidBuildFixes(config) {
  return withCleartextTraffic(withWorkManagerProguardRules(withGradleNetworkTimeout(withCmakeObjectPathMax(config))));
};
